+import React from "react";
+import classNames from "classnames";
+
+import { _t } from "../../../languageHandler";
+
+let nextDescriptionId = 0;
+
+const ExternalLink: React.FC<React.AnchorHTMLAttributes<HTMLAnchorElement>> = ({
+    children,
+    className,
+    target = "_blank",
+    rel = "noreferrer noopener",
+    "aria-describedby": describedBy,
+    ...props
+}) => {
+    const [descriptionId] = React.useState(() => `mx_ExternalLink_description_${nextDescriptionId++}`);
+    const opensNewTab = target === "_blank";
+    const safeRel = opensNewTab
+        ? Array.from(new Set([...rel.split(/\s+/), "noreferrer", "noopener"])).filter(Boolean).join(" ")
+        : rel;
+
+    return <>
+        <a
+            {...props}
+            className={classNames("mx_ExternalLink", className)}
+            target={target}
+            rel={safeRel}
+            aria-describedby={opensNewTab ? [describedBy, descriptionId].filter(Boolean).join(" ") : describedBy}
+        >
+            { children }
+            { opensNewTab && <span className="mx_ExternalLink_icon" aria-hidden="true" /> }
+        </a>
+        { opensNewTab &&
+            <span className="mx_ExternalLink_description" id={descriptionId}>{ _t("Opens in a new tab") }</span>
+        }
+    </>;
+};
+
+export default ExternalLink;
